#nullable enable // autogenerated

using PVZEngine;

namespace MVZ2Logic.Contraptions
{
    public static class LogicContraptionNames
    {
        public const string commandBlock = "command_block";
    }
    public static class LogicContraptionID
    {
        public static readonly NamespaceID commandBlock = Get(LogicContraptionNames.commandBlock);
        private static NamespaceID Get(string name)
        {
            return new NamespaceID(Global.BuiltinNamespace, name);
        }
    }
}
